                rs=[a for a,b in cl]; cs=[b for a,b in cl]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # frame = border cells only? interior zeros to fill
                frame={(a,b) for a in range(r0,r1+1) for b in range(c0,c1+1) if a in (r0,r1) or b in (c0,c1)}
                interior={(a,b) for a in range(r0+1,r1) for b in range(c0+1,c1)}
                bboxes.append((frame,interior,col,(r0,r1,c0,c1)))
                for (a,b) in cl:
                    if (a,b) not in frame: pass
    res=[row[:] for row in I]
    strays=[(r,c,v) for r in range(H) for c in range(W) if I[r][c] and I[r][c]!=0 and any((r,c) not in fr for _,fr,col,_ in bboxes)]
    # assign each stray to nearest frame bbox (manhattan to bbox box)
    from collections import defaultdict
    votes=defaultdict(int); assigns={}
    for r,c,v in strays:
        best=None
        for i,(frame,int_,fcol,br) in enumerate(bboxes):
            r0,r1,c0,c1=br
            dist=min(abs(r-r0)+abs(c-c0), abs(r-r1)+abs(c-c0), abs(r-r0)+abs(c-c1), abs(r-r1)+abs(c-c1))
            key=(dist,fcol)
