    frame_set={(a,b) for (r0,r1,c0,c1) in frames for a in range(r0,r1+1) for b in range(c0,c1+1) if a in (r0,r1) or b in (c0,c1)}
    strays=[(a,b,I[a][b]) for a in range(H) for b in range(W) if I[a][b]!=0 and (a,b) not in frame_set]
    cnt=defaultdict(int); pos={}; 
    for (a,b,v) in strays: cnt[v]+=1; pos[(a,b)]=v
    inter=sorted(frames,key=lambda ri:(ri[1]-ri[0]+1)*(ri[3]-ri[2]+1),reverse=True)
    cols=sorted(cnt.items(),key=lambda kv:-kv[1])
    res=[row[:] for row in I]
    for (a,b,v) in strays: res[a][b]=0
    for i,ri in enumerate(inter):
        r0,r1,c0,c1=ri
        fill=cols[min(i,len(cols)-1)][0]
        for (r,c) in [(a,b) for a in range(r0+1,r1) for b in range(c0+1,c1)]:
            if ((r+c)-(r0+c0))%2==0:
                res[r][c]=fill
    return res

